import heapq

def topo_sort_tasks(tasks: list[str], deps: list[tuple[str, str]]) -> list[str]:
    """Return lexicographically smallest topological ordering of `tasks`.

    Each tuple `(before, after)` in `deps` means `before` must precede `after`.
    Duplicate dependency edges are allowed and ignored.
    Raises ValueError on unknown task names or cyclic dependencies.
    """
    task_set = set(tasks)
    if len(task_set) != len(tasks):
        raise ValueError("duplicate task names")
    adj: dict[str, set[str]] = {t: set() for t in tasks}
    indeg: dict[str, int] = {t: 0 for t in tasks}
    for before, after in deps:
        if before not in task_set or after not in task_set:
            raise ValueError(f"unknown task in edge: {(before, after)!r}")
        if before == after:
            raise ValueError(f"self-dependency cycle on {before!r}")
        if after not in adj[before]:
            adj[before].add(after)
            indeg[after] += 1

    heap = [t for t in tasks if indeg[t] == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        cur = heapq.heappop(heap)
        order.append(cur)
        for nxt in adj[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(tasks):
        raise ValueError("cyclic dependency detected")
    return order
