import threading
import time
from typing import Any

class SafeTTLCache:
    """Thread-safe bounded LRU cache with monotonic TTL eviction."""

    def __init__(self, maxsize: int, ttl_sec: float):
        if maxsize <= 0 or ttl_sec <= 0:
            raise ValueError("maxsize and ttl_sec must be > 0")
        self._maxsize = maxsize
        self._ttl = ttl_sec
        self._lock = threading.Lock()
        self._data: dict[str, tuple[Any, float]] = {}

    def get(self, key: str, default: Any = None) -> Any:
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return default
            val, exp = item
            if time.monotonic() >= exp:
                del self._data[key]
                return default
            return val

    def put(self, key: str, val: Any) -> None:
        exp = time.monotonic() + self._ttl
        with self._lock:
            if len(self._data) >= self._maxsize:
                oldest = next(iter(self._data))
                del self._data[oldest]
            self._data[key] = (val, exp)

    def invalidate_prefix(self, prefix: str) -> int:
        removed = 0
        with self._lock:
            for k in self._data:
                if k.startswith(prefix):
                    del self._data[k]
                    removed += 1
            return removed
