#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint8_t *buf;
    size_t cap;
    size_t head;
    size_t tail;
    size_t len;
} ringbuf_t;

int rb_init(ringbuf_t *rb, size_t cap) {
    rb->buf = malloc(cap);
    if (!rb->buf) return -1;
    rb->cap = cap;
    rb->head = 0;
    rb->tail = 0;
    rb->len = 0;
    return 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *src, size_t n) {
    size_t free_space = rb->cap - rb->len;
    if (n > free_space) n = free_space;
    if (n == 0) return 0;
    memcpy(rb->buf + rb->head, src, n);
    rb->head = (rb->head + n) % rb->cap;
    rb->len += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *dst, size_t n) {
    if (n > rb->len) n = rb->len;
    if (n == 0) return 0;
    size_t first = rb->cap - rb->tail;
    if (first > n) first = n;
    memcpy(dst, rb->buf + rb->tail, first);
    if (n > first) {
        memcpy(dst + first, rb->buf, n - first);
    }
    rb->tail = (rb->tail + n) % rb->cap;
    rb->len -= n;
    return n;
}
